import{_ as e,o as d,c as r,a5 as a}from"./chunks/framework.D_J2JZBr.js";const f=JSON.parse('{"title":"竞赛与工程实践","description":"按芯片设计、系统、FPGA、电子与 EDA 方向选择竞赛，建立可验证、可交付的备赛流程。","frontmatter":{"title":"竞赛与工程实践","description":"按芯片设计、系统、FPGA、电子与 EDA 方向选择竞赛，建立可验证、可交付的备赛流程。"},"headers":[],"relativePath":"competitions/competitions/index.md","filePath":"competitions/competitions/index.md","lastUpdated":1795531638000}'),i={name:"competitions/competitions/index.md"};function o(n,t,s,l,c,h){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="竞赛与工程实践" tabindex="-1">竞赛与工程实践 <a class="header-anchor" href="#竞赛与工程实践" aria-label="Permalink to &quot;竞赛与工程实践&quot;">​</a></h1><p>竞赛适合把课堂知识组织成一个完整项目：需求、设计、验证、优化、交付和答辩。但竞赛不是奖项数量的比拼，也不能替代专业基础。优先选择能与你的<a href="/shanghaitech-ic-wiki-dev.github.io/learning/">学习路线</a>或科研方向相互促进的题目。</p><div class="warning custom-block"><p class="custom-block-title">年份、赛道与资格</p><p>以下月份只用于安排关注节奏，结合近年常见赛程或明确标注的 2026 年信息，不是下一届承诺。正式主办单位、年龄 / 学籍、队伍人数、赛题、AI 使用、代码授权和截止时间以当届官网为准。“适合年级”是能力建议，不是报名资格。主办与组织栏作简写，不列全部指导、承办和支持单位。</p></div><h2 id="竞赛总览" tabindex="-1">竞赛总览 <a class="header-anchor" href="#竞赛总览" aria-label="Permalink to &quot;竞赛总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>赛事</th><th>主办 / 组织</th><th>大致时间段</th><th>方向</th><th>适合阶段</th><th>备赛建议</th></tr></thead><tbody><tr><td>全国大学生集成电路创新创业大赛（集创赛）</td><td>工业和信息化部人才交流中心</td><td>通常上半年备赛，约 7–8 月决赛</td><td>数字、模拟、EDA、器件与芯片应用等企业命题</td><td>有相关基础的本科生与研究生，分赛项核查</td><td>先读企业赛题和评分口径，尽早跑通交付链路</td></tr><tr><td>全国大学生计算机系统能力大赛 CPU 设计赛（龙芯杯，NSCSCC）</td><td>全国高等学校计算机教育研究会等</td><td>上半年备赛，2026 年决赛在 8 月</td><td>CPU、系统软件与性能优化</td><td>学过体系结构和 HDL 的本科生</td><td>指令正确与测试先行，明确当年 ISA 和平台</td></tr><tr><td>全国大学生 FPGA 创新设计竞赛 / FPGA 创新设计赛道</td><td>中国电子教育学会；现以嵌入式芯片与系统设计竞赛 FPGA 赛道通知为准</td><td>2026 年首轮通知在 8 月，后续节点查当届</td><td>FPGA、可重构计算、系统实现</td><td>学过数字逻辑的本科生及研究生</td><td>先掌握时序、接口与板级调试，再追求算法效果</td></tr><tr><td>全国大学生嵌入式芯片与系统设计竞赛</td><td>中国电子教育学会及赛事组委会</td><td>芯片应用赛道常在约 2–8 月，其他赛道不同</td><td>芯片应用、芯片设计、FPGA</td><td>有编程或电路基础的学生</td><td>确认所选赛道，尽早准备硬件与完整演示</td></tr><tr><td>全国大学生电子设计竞赛</td><td>全国大学生电子设计竞赛组委会</td><td>全国赛通常在奇数年 8 月；其他年份活动另查</td><td>模拟、数字、电源、控制与测量</td><td>有实验基础的本科生</td><td>训练模块、仪器和限时协作，留出测量与文档时间</td></tr><tr><td>中国研究生电子设计竞赛（研电赛）</td><td>中国学位与研究生教育学会、中国电子学会</td><td>常见约 4–8 月，2026 年 8 月总决赛</td><td>电子系统、芯片、嵌入式与企业命题</td><td>研究生为主，资格查当届</td><td>强调系统完整性、实测证据与项目表达</td></tr><tr><td>集成电路 EDA 设计精英挑战赛，现见“中国研究生创‘芯’大赛·EDA 精英挑战赛”</td><td>中国研究生创“芯”大赛组委会</td><td>2026 年约 8–11 月</td><td>EDA 算法、工具与工业问题</td><td>研究生及符合当届组队规则的本科生</td><td>读懂评价函数、数据与资源限制，保存可复现实验</td></tr><tr><td>DAC Systems / System Design Contest（常简称 DAC SDC）</td><td>DAC 竞赛组织团队，ACM SIGDA 支持</td><td>随当届；2026 年页面未给出明确月份</td><td>系统设计、边缘 AI 等，当年题目可能变化</td><td>高年级本科生与研究生</td><td>核对设备、延迟 / 精度指标和完整提交方式</td></tr><tr><td>ICCAD CAD Contest</td><td>CAD Contest at ICCAD 组委会与产业命题方</td><td>2026 年约 5 月报名、6–8 月分阶段提交、11 月颁奖</td><td>EDA 工业算法与工具</td><td>有 C++、算法和实验基础的本科生 / 研究生</td><td>从合法输出与基线开始，迭代效率和质量</td></tr><tr><td>ISPD Contest</td><td>ISPD Contest 组织团队</td><td>通常秋冬公布题目，约次年 3–4 月会议期交流结果</td><td>物理设计、布局布线与相关优化</td><td>有算法与物理设计基础的高年级学生 / 研究生</td><td>先掌握数据格式、约束和评分，避免只调一个公开样例</td></tr></tbody></table><p>FPGA 行中的名称存在历史延续与赛道调整，不应把同一届同一赛道重复计算成两项独立比赛。EDA 精英挑战赛 2026 年规则允许本科生按规定参加，但含本科生的队伍须由研究生担任队长；不要从“研究生赛事”或旧赛名自行推断资格。</p><h2 id="怎么选一场值得投入的比赛" tabindex="-1">怎么选一场值得投入的比赛 <a class="header-anchor" href="#怎么选一场值得投入的比赛" aria-label="Permalink to &quot;怎么选一场值得投入的比赛&quot;">​</a></h2><p>先回答四个问题：目标方向是否匹配、先修是否具备、团队时间是否一致、硬件与工具资源是否有授权。再比较交付方式：是现场限时、长期开发、实物演示，还是服务器评测？这些会决定准备方法，而不仅是题目难度。</p><p>如果刚学数字电路，可从模块级 HDL 与 FPGA 小项目开始；想做 CPU 可先建立软件参考模型与验证基础；想做 EDA 应补齐 C++、数据结构和优化；喜欢模拟与测量则重视仪器、误差和安全。长线系统训练还可以了解<a href="/shanghaitech-ic-wiki-dev.github.io/competitions/projects/ysyx">一生一芯</a>，它是培养计划，不是普通竞赛。</p><h2 id="备赛的最小工程闭环" tabindex="-1">备赛的最小工程闭环 <a class="header-anchor" href="#备赛的最小工程闭环" aria-label="Permalink to &quot;备赛的最小工程闭环&quot;">​</a></h2><ol><li><strong>读规则</strong>：列出输入输出、平台、资源、禁止事项、署名与代码要求。</li><li><strong>建基线</strong>：先实现正确、可运行、可提交的版本，保存版本与结果。</li><li><strong>分工并定义接口</strong>：每个模块有负责人、测试与明确交付，不靠最后一天拼接。</li><li><strong>做实验</strong>：一次验证一个假设，保留失败证据，不只保存最好成绩。</li><li><strong>留交付缓冲</strong>：干净环境复现、完整演示、报告与答辩同样是项目的一部分。</li></ol><p>使用公开代码时遵守许可证与赛事规则，说明来源和个人贡献；禁止抄袭、违规代做及使用泄露测试。AI 工具是否允许必须逐场核查，例如 NSCSCC 2026 年决赛通知明确禁止比赛过程中使用大语言模型，不能凭平时学习习惯推断赛场许可。</p><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a>投稿备赛经验，注明年份、赛道、准备周期与技术收获；不泄露未公开赛题、内部评测数据或队友个人信息。</p></div><h2 id="官方入口与核查来源" tabindex="-1">官方入口与核查来源 <a class="header-anchor" href="#官方入口与核查来源" aria-label="Permalink to &quot;官方入口与核查来源&quot;">​</a></h2><ul><li><a href="https://univ.ciciec.com/" target="_blank" rel="noreferrer">集创赛</a> · <a href="https://www.nscscc.com/" target="_blank" rel="noreferrer">NSCSCC</a> · <a href="https://www.nscscc.com/?p=940" target="_blank" rel="noreferrer">2026 年 NSCSCC 决赛通知</a></li><li><a href="http://www.socchina.net/" target="_blank" rel="noreferrer">嵌入式芯片与系统设计竞赛</a> · <a href="http://www.fpgachina.cn/" target="_blank" rel="noreferrer">FPGA 创新设计赛道</a></li><li><a href="https://cpipc.acge.org.cn/" target="_blank" rel="noreferrer">中国研究生创新实践系列大赛平台</a> · <a href="https://cpipc.acge.org.cn/cw/hp/2c9080158ee9c272018f229208b610a6" target="_blank" rel="noreferrer">EDA 精英挑战赛与 2026 年规则</a></li><li><a href="https://www.cie.org.cn/list_42/16695.html" target="_blank" rel="noreferrer">中国电子学会：2026 年研电赛总决赛报道</a></li><li><a href="https://dac.com/2026/systems-design-contest" target="_blank" rel="noreferrer">DAC 2026 Systems Design Contest</a> · <a href="https://www.iccad-contest.org/" target="_blank" rel="noreferrer">ICCAD CAD Contest</a> · <a href="https://www.ispd.cc/" target="_blank" rel="noreferrer">ISPD</a></li></ul>',15)])])}const g=e(i,[["render",o]]);export{f as __pageData,g as default};
